import{_ as e,c as a,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const h=JSON.parse('{"title":"Products in Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/products/index.md","filePath":"master/supply-chain/inventories/products/index.md","lastUpdated":1792041590000}'),n={name:"master/supply-chain/inventories/products/index.md"};function o(i,t,c,p,d,l){return s(),a("div",null,t[0]||(t[0]=[r(`<h1 id="products-in-inventory" tabindex="-1">Products in Inventory <a class="header-anchor" href="#products-in-inventory" aria-label="Permalink to &quot;Products in Inventory&quot;">​</a></h1><p>Inventory only tracks a product when you tell it to. A product that tracks inventory is called storable. It gets a stock quantity, appears in receipts and deliveries, and shows in the stock report. This group covers the inventory side of products.</p><blockquote><p><strong>In simple words:</strong> A product becomes part of your stock when you turn on <strong>Track Inventory</strong>.</p></blockquote><p>Open the list with <code>Inventory → Products → Products</code>. The same products also show in Sales, Purchase and Manufacturing. The <strong>On Hand</strong> and <strong>Forecasted</strong> columns come from Inventory.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./configure-product.html">Configure a product</a></td><td>Track Inventory, Track By, Routes, Logistics, Update Quantity</td></tr><tr><td><a href="./product-categories.html">Product categories</a></td><td>Group products and set routes per category</td></tr><tr><td><a href="./attributes-and-packagings.html">Attributes and packagings</a></td><td>Variants and pack sizes</td></tr><tr><td><a href="./units-of-measure.html">Units of measure</a></td><td>Units and unit categories</td></tr></tbody></table><h2 id="how-the-pieces-fit" tabindex="-1">How the pieces fit <a class="header-anchor" href="#how-the-pieces-fit" aria-label="Permalink to &quot;How the pieces fit&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Category  →  Product  →  Variants (attributes)</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ├── Packagings (pack of 10)</span></span>
<span class="line"><span>                ├── Unit of measure (kg, dozen)</span></span>
<span class="line"><span>                └── Tracking (lot or serial)</span></span></code></pre></div><p>Lots, serial numbers and packages have their own group. See <a href="./../tracking/">Tracking</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The base product form (name, price, taxes) belongs to Sales. See <a href="./../../../sales/sales/products-prices/manage-products.html">Manage products</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Inventory overview</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./../tracking/">Tracking</a></li></ul>`,12)]))}const g=e(n,[["render",o]]);export{h as __pageData,g as default};
